import math
from AlgorithmImports import *


class ExactTwoSlotStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, Market.USA).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, Market.USA).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, Market.USA).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma_50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.spy_sma_200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma_50 = None
        self.previous_spy_sma_200 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {}
        self.order_slots = {}

    def OnData(self, data):
        bars = {
            symbol: self._get_bar(data, symbol)
            for symbol in self.symbols
        }

        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        previous_spy_close = self.previous_spy_close
        previous_spy_sma_50 = self.previous_spy_sma_50
        previous_spy_sma_200 = self.previous_spy_sma_200

        current_spy_close = None
        current_spy_sma_50 = None
        current_spy_sma_200 = None

        if spy_bar is not None:
            current_spy_close = float(spy_bar.Close)

            if self.spy_sma_50.IsReady:
                current_spy_sma_50 = float(self.spy_sma_50.Current.Value)

            if self.spy_sma_200.IsReady:
                current_spy_sma_200 = float(self.spy_sma_200.Current.Value)

        current_aapl_rsi = None

        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif current_aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = current_aapl_close

            if self.aapl_rsi_14.IsReady:
                current_aapl_rsi = float(self.aapl_rsi_14.Current.Value)

        if spy_bar is not None:
            self.previous_spy_close = current_spy_close

            if current_spy_sma_50 is not None:
                self.previous_spy_sma_50 = current_spy_sma_50

            if current_spy_sma_200 is not None:
                self.previous_spy_sma_200 = current_spy_sma_200

        if any(bar is None for bar in bars.values()):
            return

        spy_crosses_above_200 = (
            previous_spy_close is not None
            and previous_spy_sma_200 is not None
            and current_spy_sma_200 is not None
            and previous_spy_close <= previous_spy_sma_200
            and current_spy_close > current_spy_sma_200
        )

        spy_crosses_below_50 = (
            previous_spy_close is not None
            and previous_spy_sma_50 is not None
            and current_spy_sma_50 is not None
            and previous_spy_close >= previous_spy_sma_50
            and current_spy_close < current_spy_sma_50
        )

        aapl_rsi_above_60 = (
            current_aapl_rsi is not None
            and current_aapl_rsi > 60.0
        )

        a_shares = self._lot_shares(self.spy)
        b_shares = self._lot_shares(self.aapl)

        if (
            a_shares > 0
            and not self._has_pending_order("A")
            and spy_crosses_below_50
        ):
            self._submit_market_order(
                "A",
                self.spy,
                -a_shares,
                "Strategy A sell"
            )

        if (
            b_shares > 0
            and not self._has_pending_order("B")
            and aapl_rsi_above_60
        ):
            self._submit_market_order(
                "B",
                self.aapl,
                -b_shares,
                "Strategy B sell"
            )

        a_shares = self._lot_shares(self.spy)
        b_shares = self._lot_shares(self.aapl)

        if (
            a_shares == 0
            and not self._has_pending_order("A")
            and spy_crosses_above_200
        ):
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = math.floor(target_value / current_spy_close)

            if quantity > 0:
                self._submit_market_order(
                    "A",
                    self.spy,
                    quantity,
                    "Strategy A buy"
                )

        if (
            b_shares == 0
            and not self._has_pending_order("B")
            and self.aapl_red_streak >= 3
        ):
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= 20000.0:
                quantity = math.floor(20000.0 / float(aapl_bar.Close))

                if quantity > 0:
                    self._submit_market_order(
                        "B",
                        self.aapl,
                        quantity,
                        "Strategy B buy"
                    )

    def OnOrderEvent(self, order_event):
        slot = self.order_slots.get(order_event.OrderId)

        if slot is None:
            return

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if self.pending_orders.get(slot) == order_event.OrderId:
                del self.pending_orders[slot]

            del self.order_slots[order_event.OrderId]

    def _get_bar(self, data, symbol):
        if not data.Bars.ContainsKey(symbol):
            return None
        return data.Bars[symbol]

    def _lot_shares(self, symbol):
        return int(self.Portfolio[symbol].Quantity)

    def _has_pending_order(self, slot):
        return slot in self.pending_orders

    def _submit_market_order(self, slot, symbol, quantity, tag):
        if quantity == 0:
            return

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            return

        order_id = ticket.OrderId
        self.pending_orders[slot] = order_id
        self.order_slots[order_id] = slot

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders.pop(slot, None)
            self.order_slots.pop(order_id, None)

from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {
            "A": False,
            "B": False
        }

        self.order_slots = {
            "A_BUY": "A",
            "A_SELL": "A",
            "B_BUY": "B",
            "B_SELL": "B"
        }

    def _get_bar(self, data, symbol):
        if not data.Bars.ContainsKey(symbol):
            return None

        bar = data.Bars[symbol]
        if bar.IsFillForward:
            return None

        return bar

    def OnData(self, data):
        spy_bar = self._get_bar(data, self.spy)
        aapl_bar = self._get_bar(data, self.aapl)
        ibm_bar = self._get_bar(data, self.ibm)
        bac_bar = self._get_bar(data, self.bac)
        aig_bar = self._get_bar(data, self.aig)

        spy_close = None
        aapl_close = None

        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            self.spy_sma_200.Update(spy_bar.EndTime, spy_close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_close)

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        all_bars_present = (
            spy_bar is not None and
            aapl_bar is not None and
            ibm_bar is not None and
            bac_bar is not None and
            aig_bar is not None
        )

        if all_bars_present and not self.IsWarmingUp:
            current_sma_200 = (
                float(self.spy_sma_200.Current.Value)
                if self.spy_sma_200.IsReady else None
            )
            current_sma_50 = (
                float(self.spy_sma_50.Current.Value)
                if self.spy_sma_50.IsReady else None
            )

            strategy_a_buy = (
                current_sma_200 is not None and
                self.previous_spy_close is not None and
                self.previous_spy_sma_200 is not None and
                self.previous_spy_close <= self.previous_spy_sma_200 and
                spy_close > current_sma_200
            )

            strategy_a_sell = (
                current_sma_50 is not None and
                self.previous_spy_close is not None and
                self.previous_spy_sma_50 is not None and
                self.previous_spy_close >= self.previous_spy_sma_50 and
                spy_close < current_sma_50
            )

            strategy_b_buy = self.aapl_red_streak >= 3

            strategy_b_sell = (
                self.aapl_rsi_14.IsReady and
                float(self.aapl_rsi_14.Current.Value) > 60
            )

            if (
                self.lots["A"] > 0 and
                not self.pending_orders["A"] and
                strategy_a_sell
            ):
                self._place_order(
                    "A",
                    self.spy,
                    -self.lots["A"],
                    "A_SELL"
                )

            if (
                self.lots["B"] > 0 and
                not self.pending_orders["B"] and
                strategy_b_sell
            ):
                self._place_order(
                    "B",
                    self.aapl,
                    -self.lots["B"],
                    "B_SELL"
                )

            if (
                self.lots["A"] == 0 and
                not self.pending_orders["A"] and
                strategy_a_buy
            ):
                target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
                quantity = int(target_value / spy_close)

                if quantity > 0:
                    self._place_order(
                        "A",
                        self.spy,
                        quantity,
                        "A_BUY"
                    )

            if (
                self.lots["B"] == 0 and
                not self.pending_orders["B"] and
                strategy_b_buy
            ):
                if self.Portfolio.Cash >= 20000:
                    quantity = int(20000 / aapl_close)

                    if quantity > 0:
                        self._place_order(
                            "B",
                            self.aapl,
                            quantity,
                            "B_BUY"
                        )

        if spy_bar is not None:
            self.previous_spy_close = spy_close

            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = float(
                    self.spy_sma_200.Current.Value
                )

            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = float(
                    self.spy_sma_50.Current.Value
                )

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_close

    def _place_order(self, slot, symbol, quantity, tag):
        if quantity == 0 or self.pending_orders[slot]:
            return

        self.pending_orders[slot] = True
        ticket = self.MarketOrder(symbol, quantity, False, tag)

        if ticket is None:
            self.pending_orders[slot] = False
        elif ticket.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            self.pending_orders[slot] = False

    def OnOrderEvent(self, orderEvent):
        order = self.Transactions.GetOrderById(orderEvent.OrderId)
        if order is None or order.Tag not in self.order_slots:
            return

        slot = self.order_slots[order.Tag]
        fill_quantity = int(orderEvent.FillQuantity)

        if fill_quantity != 0:
            self.lots[slot] = max(
                0,
                self.lots[slot] + fill_quantity
            )

        if orderEvent.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[slot] = False
